"use client";
import { ScrollAreaList } from "@/components/ui/scroll-area";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Command as Primitive } from "cmdk";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { InputWrapper, InputControl } from "@/components/ui/input";
import { AnimatedIcon } from "@/components/ui/animated-icon";
import { Icon, Disk } from "@/components/ui/icon";
import { useCommandResultsMotion } from "@/components/ui/command";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/sahajiv-motion/use-flow";
import { ItemAdornment, itemText, type ItemAdornmentItemProps, type ItemAdornmentValue } from "@/components/ui/item-adornment";
export type ComboboxOption = {
  value: string;
  label: string;
  disabled?: boolean;
  adornment?: ItemAdornmentValue;
};
type ComboboxState = {
  open: boolean;
  setOpen: (open: boolean) => void;
  selected: string;
  select: (value: string, label: string) => void;
  query: string;
  setQuery: (value: string) => void;
  listId: string;
};
const ComboboxContext = React.createContext<ComboboxState | null>(null);
const ComboboxInputRefContext = React.createContext<
  React.RefCallback<HTMLInputElement> | undefined
>(undefined);
function useCombobox() {
  const context = React.useContext(ComboboxContext);
  if (!context) throw new Error("Combobox parts must be inside Combobox");
  return context;
}
export const comboboxVariants = cva("v-combo [position:relative]");
export type ComboboxProps = Omit<
  React.ComponentProps<typeof Primitive>,
  "value" | "defaultValue" | "onValueChange"
> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  options?: ComboboxOption[];
  placeholder?: string;
  emptyText?: string;
  "aria-label"?: string;
};
export function Combobox({
  className,
  children,
  value,
  defaultValue = "",
  onValueChange,
  open,
  defaultOpen = false,
  onOpenChange,
  options,
  placeholder,
  emptyText = "No matches",
  ...props
}: ComboboxProps) {
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const selected = value ?? internalValue;
  const selectedLabel =
    options?.find((option) => option.value === selected)?.label ?? selected;
  const selectionKey = JSON.stringify([selected, selectedLabel]);
  const [search, setSearch] = React.useState({
    selection: selectionKey,
    query: selectedLabel,
  });
  const query =
    search.selection === selectionKey ? search.query : selectedLabel;
  const setQuery = (next: string) =>
    setSearch({ selection: selectionKey, query: next });
  const listId = React.useId();
  const inputRef = React.useRef<HTMLInputElement>(null);
  const registerInput = React.useCallback((node: HTMLInputElement | null) => {
    inputRef.current = node;
  }, []);
  const isOpen = open ?? internalOpen;
  const setOpen = (next: boolean) => {
    setInternalOpen(next);
    onOpenChange?.(next);
  };
  const select = (next: string, label: string) => {
    setInternalValue(next);
    onValueChange?.(next);
    setSearch({
      selection: JSON.stringify([
        next,
        options?.find((option) => option.value === next)?.label ?? next,
      ]),
      query: label,
    });
    setOpen(false);
    inputRef.current?.focus();
  };
  return (
    <ComboboxContext.Provider
      value={{
        open: isOpen,
        setOpen,
        selected,
        select,
        query,
        setQuery,
        listId,
      }}
    >
      <ComboboxInputRefContext.Provider value={registerInput}>
        <PopoverPrimitive.Root open={isOpen} onOpenChange={setOpen}>
          <Primitive
            data-slot="combobox"
            data-part="root"
            data-combo=""
            data-state={isOpen ? "open" : "closed"}
            className={cn(comboboxVariants(), className)}
            {...props}
          >
            {children ?? (
              <>
                <ComboboxInput
                  placeholder={placeholder}
                  aria-label={props["aria-label"] ?? "Choose an option"}
                />
                <ComboboxContent>
                  <ComboboxEmpty>{emptyText}</ComboboxEmpty>
                  {options?.map((option) => (
                    <ComboboxItem
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      disabled={option.disabled}
                      adornment={option.adornment}
                    >
                      {option.label}
                    </ComboboxItem>
                  ))}
                </ComboboxContent>
              </>
            )}
          </Primitive>
        </PopoverPrimitive.Root>
      </ComboboxInputRefContext.Provider>
    </ComboboxContext.Provider>
  );
}
export type ComboboxInputProps = React.ComponentProps<
  typeof Primitive.Input
> & {
  wrapperProps?: React.ComponentProps<typeof InputWrapper>;
  leading?: React.ReactNode;
};
export function ComboboxInput({
  className,
  wrapperProps,
  leading,
  onValueChange,
  onFocus,
  onKeyDown,
  ...props
}: ComboboxInputProps) {
  const state = useCombobox();
  const inputRef = React.useContext(ComboboxInputRefContext);
  return (
    <PopoverPrimitive.Anchor asChild>
      <InputWrapper {...wrapperProps}>
        {leading ?? (
          <Disk size="sm">
            <Icon name="search" />
          </Disk>
        )}
        <Primitive.Input
          ref={inputRef}
          asChild
          value={state.query}
          onValueChange={(next) => {
            state.setQuery(next);
            state.setOpen(true);
            onValueChange?.(next);
          }}
        >
          <InputControl
            data-slot="combobox-input"
            data-part="trigger"
            className={className}
            aria-expanded={state.open}
            aria-controls={state.listId}
            onFocus={(event: React.FocusEvent<HTMLInputElement>) => {
              state.setOpen(true);
              onFocus?.(event);
            }}
            onKeyDown={(event: React.KeyboardEvent<HTMLInputElement>) => {
              onKeyDown?.(event);
              if (event.defaultPrevented) return;
              if (event.key === "Escape") {
                event.preventDefault();
                state.setOpen(false);
              } else if (event.key === "ArrowDown" || event.key === "ArrowUp")
                state.setOpen(true);
            }}
            {...props}
          />
        </Primitive.Input>
      </InputWrapper>
    </PopoverPrimitive.Anchor>
  );
}
export type ComboboxContentProps = React.ComponentProps<typeof Primitive.List>;
export function ComboboxContent({
  className,
  children,
  ref,
  style,
  ...props
}: ComboboxContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces");
  const state = useCombobox();
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[aria-selected=true]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(
    state.open,
    groupRef,
    "grow",
  );
  const resultsRef = useCommandResultsMotion(ref);
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        ref={flowRef}
        data-slot="combobox-content"
        data-part="content"
        className={cn("v-menu", className)}
        style={style}
        sideOffset={6}
        collisionPadding={12}
        onCloseAutoFocus={(event) => event.preventDefault()}
        onOpenAutoFocus={(event) => event.preventDefault()}
        onInteractOutside={(event) => {
          if (
            event.target instanceof Element &&
            event.target.closest('[data-slot="combobox"]')
          )
            event.preventDefault();
        }}
      >
        <ScrollAreaList maxHeight="min(280px, calc(var(--radix-popover-content-available-height, 60dvh) - 20px))">
        <Primitive.List
          ref={resultsRef}
          id={state.listId}
          data-slot="combobox-list"
          data-part="content"
          className="v-command-results"
          {...props}
        >{children}</Primitive.List>
        </ScrollAreaList>
      </PopoverPrimitive.Content>
    </PopoverPrimitive.Portal>
  );
}
export const ComboboxList = ComboboxContent;
export type ComboboxItemProps = React.ComponentProps<typeof Primitive.Item> & {
  label?: string;
  showIndicator?: boolean;
} & ItemAdornmentItemProps;
export function ComboboxItem({
  showIndicator = true,
  className,
  adornment,
  adornmentId,
  children,
  onSelect,
  label,
  value,
  ref,
  ...props
}: ComboboxItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  const state = useCombobox();
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="combobox-item"
      data-selected-option={state.selected === value || undefined}
      data-part="item"
      className={cn("v-menu__item", className)}
      value={value}
      keywords={label ? [label] : undefined}
      onSelect={(next) => {
        state.select(
          value ?? next,
          label ?? (typeof children === "string" ? children : next),
        );
        onSelect?.(next);
      }}
      {...props}
    >
      <ItemAdornment identity={adornmentId ?? value ?? label ?? itemText(children)} value={adornment} />
      <span className="v-combo__label">{children}</span>
      {showIndicator && state.selected === value && <span className="v-combo__selected" aria-hidden="true"><AnimatedIcon name="check" preset="validation" /></span>}
    </Primitive.Item>
  );
}
export type ComboboxEmptyProps = React.ComponentProps<typeof Primitive.Empty>;
export function ComboboxEmpty({ className, ...props }: ComboboxEmptyProps) {
  return (
    <Primitive.Empty
      data-slot="combobox-empty"
      data-part="empty"
      className={cn("p-3 text-[color:var(--v-text-2)]", className)}
      {...props}
    />
  );
}
export type ComboboxGroupProps = React.ComponentProps<typeof Primitive.Group>;
export function ComboboxGroup(props: ComboboxGroupProps) {
  return (
    <Primitive.Group data-slot="combobox-group" data-part="group" {...props} />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  background: var(--popover);
  border-radius: var(--r-card-sm);
  padding: var(--s-2);
  min-width: 200px;
  box-shadow: var(--shadow-float);
  border: 1px solid var(--v-border);
  display: grid;
  gap: 2px;
}
.v-menu__item:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where([data-slot="combobox"], [data-slot^="combobox-"]):hover,
.v-menu__item:where(
    [data-slot="combobox"],
    [data-slot^="combobox-"]
  )[aria-selected="true"] {
  background: var(--v-beige);
}
.v-menu__item:where([data-slot="combobox"], [data-slot^="combobox-"]).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-menu__group:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  padding: 8px 12px 4px;
}
[data-slot="combobox-content"] {
  z-index: var(--z-dialog);
  max-height: none;
  overflow: visible;
}
[data-slot="combobox-item"]
  mark {
  background: var(--v-yellow);
  border-radius: 3px;
  padding: 0 1px;
}
[data-slot="combobox-item"] {
  display: block;
  line-height: 40px;
  padding: 0 var(--s-3);
}
[data-slot="combobox-item"]
  mark {
  background: var(--v-yellow);
  color: var(--v-on-accent);
  border-radius: 3px;
  padding: 0 1px;
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"]) .v-input {
  height: var(--ctl-lg);
  padding: 0 16px 0 8px;
  gap: 12px;
  background: var(--input);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input
  > .v-disk {
  width: 32px;
  height: 32px;
  margin: 0;
  background: var(--v-canvas);
  color: var(--v-text-2);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input
  > .v-disk
  .v-icon {
  width: 16px;
  height: 16px;
  stroke-width: 2;
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input:focus-within {
  background: var(--v-pink-soft);
  box-shadow: inset 0 0 0 2px var(--v-brand);
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input:focus-within
  > .v-disk {
  color: var(--v-text);
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input
  input {
  font-size: var(--fs-body);
  color: var(--v-text);
}
[data-slot="combobox-content"] {
  padding: 6px;
  border-radius: 16px;
}
.v-menu:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where(
    [data-slot="combobox"],
    [data-slot^="combobox-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-menu:where(
    [data-slot="combobox"],
    [data-slot^="combobox-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-menu:where(
    [data-slot="combobox"],
    [data-slot^="combobox-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input
  > .v-disk {
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  background: var(--v-pink);
  color: var(--v-on-accent);
  box-shadow: none;
}
.v-combo:where([data-slot="combobox"], [data-slot^="combobox-"])
  .v-input:focus-within
  > .v-disk {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
[data-slot="combobox-content"] {
  display: grid;
  gap: 2px;
  padding: 6px;
  border-radius: 18px;
  box-shadow:
    var(--shadow-float),
    inset 0 0 0 1px var(--v-border);
  border: 0;
}
[data-slot="combobox-item"] {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  line-height: 1.3;
  padding: 0 10px 0 8px;
  border-radius: 12px;
  white-space: normal;
}
[data-slot="combobox-item"]
  > span:not(.v-disk,.v-item-adornment),
[data-slot="combobox-item"]
  .v-combo__label {
  grid-column: 2;
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
[data-slot="combobox-item"]
  mark {
  display: inline;
}
[data-slot="combobox-item"]:hover,
[data-slot="combobox-item"][aria-selected="true"] {
  background: var(--v-pink-soft);
  color: var(--v-text);
}
[data-slot="combobox-item"][aria-selected="true"]::after {
  content: "";
  grid-column: 3;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--v-text);
}
[data-slot="combobox-item"]
  mark {
  background: transparent;
  color: inherit;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: var(--v-pink-deep);
  text-decoration-thickness: 2px;
  text-underline-offset: 2px;
  padding: 0;
  border-radius: 0;
}
.v-menu:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="combobox"], [data-slot^="combobox-"]) {
  scrollbar-gutter: stable;
}
:root[data-mode="dark"]
  [data-slot="combobox-content"] {
  background: var(--v-beige);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="combobox"],
  [data-slot^="combobox-"],
  [data-slot="combobox"]::before,
  [data-slot="combobox"]::after,
  [data-slot^="combobox-"]::before,
  [data-slot^="combobox-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="combobox-content"] {
  width: var(--radix-popover-trigger-width);
  max-width: calc(100vw - 24px);
}
[data-slot="combobox-content"] > [cmdk-list-sizer],
[data-slot="combobox-content"] [cmdk-group-items] {
  display: contents;
}
[data-slot="combobox-content"] [cmdk-group][hidden] {
  display: none;
}
[data-slot="combobox-item"][data-disabled="true"] {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}

/* Portalled list keeps its own surface, bounds, and wrapping contract. */
[data-slot="combobox-content"] {
  min-width: 0;
  max-height: min(280px, var(--radix-popover-content-available-height));
  overscroll-behavior: contain;
}
[data-slot="combobox-item"] { padding-block: 8px; text-align: start; }
[data-slot="combobox-item"] .v-combo__label { overflow-wrap: anywhere; }
[data-slot="combobox-item"][data-disabled="true"] { background: transparent; color: var(--v-disabled-ink); }
[data-slot="combobox-item"][data-disabled="true"]::before { background: var(--v-disabled-fill); }

/* Nested menus live above dialog surfaces as well as the document. */
[data-slot="combobox-content"] { z-index: var(--z-popover); }

/* cmdk's contents-only sizer has no stacking box: each option sits above the moving selection paint. */
[data-flow-owned][data-slot="combobox-content"] [data-slot="combobox-item"] { position: relative; z-index: 1; }

[data-slot="combobox-item"] { grid-template-columns:30px minmax(0,1fr) auto; min-height:46px; }
[data-slot="combobox-item"] > .v-item-adornment { grid-column:1; display:inline-grid; overflow:visible; }
[data-slot="combobox-item"]:not(:has(.v-item-adornment)) { grid-template-columns:minmax(0,1fr) auto; }
[data-slot="combobox-item"]:not(:has(.v-item-adornment)) > .v-combo__label { grid-column:1; }
[data-slot="combobox-item"]:active:not([data-disabled="true"]) { background:var(--v-pink-soft); color:var(--v-text); }

[data-slot="combobox-item"] > .v-combo__selected { margin-inline-start: auto; display: inline-flex; flex: none; padding-inline-start: 8px; }
[data-slot="combobox-item"] > .v-combo__selected .v-icon { width: 16px; height: 16px; }

}
